const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Kandidat
  if (data.property_geburtsdatum) {
    let maxDistanz = 50;
    let foundField = 'nicht gefunden';

    for (const key of Object.keys(data)) {
      if (key.toLowerCase().includes('distanz')) {
        foundField = key + ' = ' + data[key];
        const match = String(data[key]).match(/\d+/);
        if (match) maxDistanz = parseInt(match[0]);
        break;
      }
    }

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_wohnadresse,
        max_distanz_km: maxDistanz,
        debug_field: foundField,
        type: 'kandidat'
      }
    });
  }
  // Fachgeschäft
  else if (data.property_adresse) {
    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        type: 'shop'
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const geo = items[i].json;
  const orig = $('DEBUG Extrahieren').all()[i].json;

  if (geo.status === 'OK' && geo.results[0]) {
    const loc = geo.results[0].geometry.location;
    results.push({
      json: {
        ...orig,
        lat: loc.lat,
        lng: loc.lng
      }
    });
  }
}

return results;

const all = $input.first().json.data;
const kandidaten = all.filter(x => x.type === 'kandidat');
const shops = all.filter(x => x.type === 'shop');

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const results = [];

for (const k of kandidaten) {
  const allShops = [];

  for (const s of shops) {
    const d = distance(k.lat, k.lng, s.lat, s.lng);
    const dist = Math.round(d*10)/10;
    allShops.push({
      name: s.name,
      dist: dist,
      max_erlaubt: k.max_distanz_km,
      passt: d <= k.max_distanz_km ? 'JA' : 'NEIN'
    });
  }

  results.push({
    json: {
      kandidat: k.name,
      max_distanz_km: k.max_distanz_km,
      debug_field: k.debug_field,
      alle_shops: allShops
    }
  });
}

return results;
